#include <FastLED.h>

// ========================================
// Hardware
// ========================================

#define BASE_PIN       6
#define FLOWER_PIN     7

#define BASE_COUNT     24
#define FLOWER_COUNT   6

#define LED_TYPE       WS2812B
#define COLOR_ORDER    GRB

#define MAX_CURRENT_MA 500

CRGB base[BASE_COUNT];
CRGB flowers[FLOWER_COUNT];

const CRGB BASE_COLOR   = CRGB(255, 18, 75);
const CRGB FLOWER_COLOR = CRGB(255, 70, 150);

// ========================================
// Animation
// ========================================

struct Pixel {
  uint8_t brightness;
  uint8_t target;
  uint8_t pauseCount;
  int8_t phase;       // 0=Warten, 1=Einblenden,
                      // 2=Pause, 3=Ausblenden
  uint32_t nextTime;
};

Pixel baseState[BASE_COUNT];
Pixel flowerState[FLOWER_COUNT];

uint32_t nextBaseSpawn = 0;
uint32_t nextFlowerSpawn = 0;

// ========================================
// Pixel starten
// ========================================

void startPixel(Pixel &p) {
  p.brightness = 0;
  p.target = random(100, 256);
  p.phase = 1;
  p.nextTime = millis();
}

void spawnRandom(Pixel states[], int count) {
  for (int attempt = 0; attempt < count; attempt++) {
    int i = random(count);

    if (states[i].phase == 0) {
      startPixel(states[i]);
      return;
    }
  }
}

// ========================================
// Animation aktualisieren
// ========================================

void updatePixel(Pixel &p) {
  uint32_t now = millis();

  switch (p.phase) {
    case 0:
      // Inaktive LEDs bleiben dunkel.
      break;

    case 1:
      // Einblenden
      if (p.brightness < p.target) {
        p.brightness = min(
          (int)p.target,
          (int)p.brightness + 3
        );
      } else {
        p.phase = 2;
        p.nextTime = now + random(250, 1000);
      }
      break;

    case 2:
      // Leuchtpause
      if (now >= p.nextTime) {
        p.phase = 3;
      }
      break;

    case 3:
      // Ausblenden
      if (p.brightness > 3) {
        p.brightness -= 3;
      } else {
        p.brightness = 0;
        p.phase = 0;
        p.nextTime = now + random(100, 1200);
      }
      break;
  }
}

// ========================================
// LEDs darstellen und Strom schätzen
// ========================================

uint32_t estimateCurrent(
  const CRGB color,
  Pixel states[],
  int count
) {
  uint32_t estimate = 0;

  for (int i = 0; i < count; i++) {
    uint32_t channelSum =
      (uint32_t)color.r + color.g + color.b;

    estimate +=
      (channelSum * states[i].brightness * 20UL)
      / (255UL * 255UL);
  }

  return estimate;
}

void renderWithLimit() {
  uint32_t flowerEstimate =
    estimateCurrent(FLOWER_COLOR, flowerState, FLOWER_COUNT);

  uint32_t baseEstimate =
    estimateCurrent(BASE_COLOR, baseState, BASE_COUNT);

  float flowerScale = 1.0f;
  float baseScale = 1.0f;

  if (flowerEstimate >= MAX_CURRENT_MA) {
    flowerScale =
      (float)MAX_CURRENT_MA /
      (float)max((uint32_t)1, flowerEstimate);

    baseScale = 0.0f;
  } else {
    uint32_t remaining = MAX_CURRENT_MA - flowerEstimate;

    if (baseEstimate > remaining && baseEstimate > 0) {
      baseScale = (float)remaining / baseEstimate;
    }
  }

  // Base-LEDs
  for (int i = 0; i < BASE_COUNT; i++) {
    base[i] = BASE_COLOR;
    base[i].nscale8(baseState[i].brightness);
    base[i].nscale8((uint8_t)(baseScale * 255.0f));
  }

  // Blumen-LEDs
  for (int i = 0; i < FLOWER_COUNT; i++) {
    flowers[i] = FLOWER_COLOR;
    flowers[i].nscale8(flowerState[i].brightness);
    flowers[i].nscale8((uint8_t)(flowerScale * 255.0f));
  }

  FastLED.show();
}

// ========================================
// Setup
// ========================================

void setup() {
  delay(300);

  // Zufall initialisieren, ohne esp_system.h
  randomSeed(analogRead(0));

  FastLED.addLeds<LED_TYPE, BASE_PIN, COLOR_ORDER>(
    base, BASE_COUNT
  );

  FastLED.addLeds<LED_TYPE, FLOWER_PIN, COLOR_ORDER>(
    flowers, FLOWER_COUNT
  );

  FastLED.setBrightness(255);
  FastLED.clear(true);

  for (int i = 0; i < BASE_COUNT; i++) {
    baseState[i] = {0, 0, 0, 0, 0};
  }

  for (int i = 0; i < FLOWER_COUNT; i++) {
    flowerState[i] = {0, 0, 0, 0, 0};
  }

  // Sofort mit zufälligen LEDs starten
  for (int i = 0; i < 5; i++) {
    spawnRandom(baseState, BASE_COUNT);
    spawnRandom(flowerState, FLOWER_COUNT);
  }

  nextBaseSpawn = millis() + 200;
  nextFlowerSpawn = millis() + 300;
}

// ========================================
// Hauptschleife
// ========================================

void loop() {
  uint32_t now = millis();

  for (int i = 0; i < BASE_COUNT; i++) {
    updatePixel(baseState[i]);
  }

  for (int i = 0; i < FLOWER_COUNT; i++) {
    updatePixel(flowerState[i]);
  }

  if (now >= nextBaseSpawn) {
    spawnRandom(baseState, BASE_COUNT);
    nextBaseSpawn = now + random(180, 650);
  }

  if (now >= nextFlowerSpawn) {
    spawnRandom(flowerState, FLOWER_COUNT);
    nextFlowerSpawn = now + random(250, 900);
  }

  renderWithLimit();
  delay(20);
}
